WITH unpacked AS (SELECT id, customer_id, created_at, items, ship_to, ARRAY_CONTAINS(MAP_KEYS(attributes), 'utm_source') AS has_utm_source, ship_to.city AS ship_city FROM carts WHERE customer_id IS NULL) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(*) AS event_count, COUNT_IF(ship_city = 'Chiang Mai') AS chiang_mai_events, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes FROM unpacked GROUP BY DATE_TRUNC('HOUR', created_at), DATE_TRUNC('DAY', created_at) ORDER BY hour_window NULLS LAST;
